#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<int> d(n);
    for (auto &x : d) scanf("%d", &x);
    int best = -1; // site rule: -1 when no valid three-digit number exists
    for (int i = 0; i + 2 < n; i++) {
        if (d[i] == 0) continue;
        for (int j = i + 1; j + 1 < n; j++)
            for (int k = j + 1; k < n; k++) best = max(best, d[i] * 100 + d[j] * 10 + d[k]);
    }
    printf("%d\n", best);
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] d = new int[n];
        for (int i = 0; i < n; i++) d[i] = sc.nextInt();
        int best = -1; // site rule: -1 when no valid three-digit number exists
        for (int i = 0; i + 2 < n; i++) {
            if (d[i] == 0) continue;
            for (int j = i + 1; j + 1 < n; j++)
                for (int k = j + 1; k < n; k++) best = Math.max(best, d[i] * 100 + d[j] * 10 + d[k]);
        }
        System.out.println(best);
    }
}

